from zoneinfo import ZoneInfo

def available(window: tuple[int, int], busy: list[tuple[int, int]]) -> list[tuple[int, int]]:
    left, right = window
    result = []
    for start, stop in busy:
        if start > left:
            result.append((left, start))
        left = stop
    if left < right:
        result.append((left, right))
    return result

