import csv
from pathlib import Path

def load(path: Path) -> list[dict]:
    with path.open(encoding="utf-8", newline="") as stream:
        return [
            {"category": row["category"], "cents": int(row["cents"])}
            for row in csv.DictReader(stream)
        ]

